#!/bin/sh
# BenchKit external load generator.
#
# Generated by the BenchKit server you are testing, so the load this machine
# drives is exactly the standard load a self-test would run. It handshakes,
# then waits for the run to reach its web server stage and fires automatically.
#
# What it needs: oha on your PATH. What it installs: nothing. If oha is
# missing this script stops and tells you how to install it yourself. It
# writes one temporary file, removes it, and never needs root. Everything it
# runs comes from the BenchKit server named in the command you pasted.
set -eu

BASE={!! $base !!}
TARGET={!! $target !!}
TOKEN={!! $token !!}
CURL="curl {!! $curlInsecure !!} -sS"

@include('bench.partials.generator-style')

# oha via Homebrew lands on PATH; a cargo build or a dropped-in release
# binary may not.
PATH="$PATH:$HOME/.cargo/bin:$HOME/.local/bin"

blank
printf '  %s%sBenchKit%s %sexternal load generator%s\n' "$C_BOLD" "$C_BRAND" "$C_RESET" "$C_DIM" "$C_RESET"

# Each block below opens with its own blank line, and fail() brings one too,
# so a preflight failure does not land under a double gap.
if ! command -v oha >/dev/null 2>&1; then
    # oha ships one plain binary per platform, so naming the exact asset for
    # the machine already running this turns the fix into a copy-paste
    # instead of a hunt through a releases page.
    case "$(uname -s 2>/dev/null)/$(uname -m 2>/dev/null)" in
        Linux/x86_64|Linux/amd64) OHA_ASSET=oha-linux-amd64 ;;
        Linux/aarch64|Linux/arm64) OHA_ASSET=oha-linux-arm64 ;;
        Darwin/x86_64) OHA_ASSET=oha-macos-amd64 ;;
        Darwin/arm64) OHA_ASSET=oha-macos-arm64 ;;
        *) OHA_ASSET='' ;;
    esac

    if [ -n "$OHA_ASSET" ]; then
        OHA_BINARY="    Or put the release binary on this machine yourself:

      mkdir -p ~/.local/bin
      curl -fsSL https://github.com/hatoo/oha/releases/latest/download/$OHA_ASSET -o ~/.local/bin/oha
      chmod +x ~/.local/bin/oha

    This command looks in ~/.local/bin and ~/.cargo/bin, so a binary in
    either is found without changing your PATH."
    else
        OHA_BINARY='    Release binaries: https://github.com/hatoo/oha/releases'
    fi

    fail 'oha is not installed on this machine.' \
"    This script will not install it for you. Install oha, then run the
    BenchKit command again.

      macOS        brew install oha
      Arch Linux   pacman -S oha
      Windows      run the BenchKit command inside WSL

$OHA_BINARY"
fi

OHA_VERSION=$(oha --version 2>/dev/null | head -n 1 | sed 's/^oha //; s/[^0-9A-Za-z._+-]//g' | cut -c1-20)

blank
step "oha ${OHA_VERSION:-installed}"

BODY=$($CURL --max-time 5 "$TARGET/bench/static" 2>/dev/null || true)
[ "$BODY" = 'BenchKit OK' ] || fail "Could not reach $TARGET from this machine." \
'    Check the URL and any firewall between the two machines. This machine
    needs a clear path to the server.'

step "$TARGET is reachable"

# The floor of five requests on one kept-alive connection approximates the
# round trip, and the server shows it as a ceiling before the run starts: a
# closed-loop generator cannot exceed connections / RTT no matter how fast
# the server is. One curl invocation reuses the connection, so only the
# first request pays for the TCP and TLS handshakes — the same footing oha's
# kept-alive connections run on.
RTT=$($CURL -w '%{time_total}\n' \
    -o /dev/null "$TARGET/bench/static" -o /dev/null "$TARGET/bench/static" \
    -o /dev/null "$TARGET/bench/static" -o /dev/null "$TARGET/bench/static" \
    -o /dev/null "$TARGET/bench/static" | sort -n | head -n 1)
RTT_MS=$(awk -v t="$RTT" 'BEGIN { printf "%.2f", t * 1000 }')

CORES=$( (nproc 2>/dev/null || sysctl -n hw.ncpu 2>/dev/null || echo 0) | head -n 1 | tr -dc '0-9')
HOST=$(hostname 2>/dev/null | cut -c1-60 | sed 's/[\\"]//g')

$CURL -o /dev/null -X POST -H 'Content-Type: application/json' \
    -d "{\"oha_version\":\"$OHA_VERSION\",\"cores\":${CORES:-0},\"host\":\"$HOST\",\"rtt_ms\":$RTT_MS}" \
    "$BASE/bench/generator/$TOKEN/handshake" \
    || fail 'The server did not accept the handshake.' \
'    The pairing may have expired or been replaced. Start over in BenchKit
    to get a new command.'

step "Connected ${C_DIM}·${C_RESET}${C_TEXT} ${RTT_MS}ms round trip"

blank
note 'Waiting for the run to reach its web server stage.'
note 'Leave this terminal open. It starts on its own.'

WORK=$(mktemp)
TICKS=0

while :; do
    CODE=$($CURL -o "$WORK" -w '%{http_code}' "$BASE/bench/generator/$TOKEN/work" 2>/dev/null || echo 000)

    case "$CODE" in
        200) break ;;
        404|410)
            rm -f "$WORK"
            if [ -n "$TTY" ]; then printf '%s' "$ERASE"; fi
            fail 'This pairing is no longer valid.' \
'    The run finished, was cancelled, or a newer command replaced this one.
    Start over in BenchKit to get a new command.' ;;
    esac

    TICKS=$((TICKS + 1))

    # On a terminal the wait redraws one line; piped to a log it stays quiet
    # until there is something worth a new line.
    if [ -n "$TTY" ]; then
        printf '%s  %sWaiting… %ss%s' "$ERASE" "$C_DIM" "$((TICKS * 2))" "$C_RESET"
    elif [ $((TICKS % 15)) -eq 0 ]; then
        note "Still waiting… ($((TICKS * 2))s elapsed)"
    fi

    sleep 2
done

if [ -n "$TTY" ]; then printf '%s' "$ERASE"; fi

sh "$WORK"
rm -f "$WORK"

blank
step 'Load test complete'
blank
note 'The results are on the BenchKit server.'
note 'You can close this terminal.'
blank
